Definition malloc_head_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo size needed rz c CA P TSD CTX TH sb TOP BOT : Z) (T : list Z) (d : depot) (mc : word) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 : word) (jk j8 : list byte) (rest : list word) m',
    ms' = MS (mkR (wz 0x54ac4) (Z_to_bv 64 (bv_unsigned sp + -2320)) gp tp t0 t1 t2 (Z_to_bv 64 c) (wz P) (wz CA) (wz P) (wz AINST)
                  (Z_to_bv 64 c) a4 a5 a6 a7 (wz 8) (wz CA) (wz AINST) (wz size) (wz AINST) (wz (bv_unsigned sp + -2128))
                  (Z_to_bv 64 (-8)) (wz 7) (wz TH) (wz 1) t3 t4 t5 t6)
             F (Z_to_bv 64 0x54f64) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (TH + 3168, TH + 3169)] m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ AENV tp TSD CTX TH sb (bv_unsigned sp + -2128) T rest m' /\ length rest = (255 - length T)%nat
    /\ Forall (fun x => 0 <= x < 2^64) T /\ (1 <= length T <= 30)%nat
    /\ stk bsegs m' lo (bv_unsigned sp + -2320)
    /\ rw_cells bsegs m' (bv_unsigned sp + -2320) [C8 (wz rz); C8 (wz needed); C8 (wz 8); C8 (wz size); C8 (wz 1); C8 (wz 0x5035c)]
    /\ aframe (Z_to_bv 64 (bv_unsigned sp + -2144)) (wz 0x5008c) sp (wz size) (wz 0x0747e8) (wz 1)
              (Z_to_bv 64 (bv_unsigned sp + -2128)) (Z_to_bv 64 (bv_unsigned sp + -81)) s6 s7 s8 s9 s10 s11 m' j8
    /\ rw_cells bsegs m' (bv_unsigned sp + -2144) [C8 sp; C8 (wz 0x074854)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -72) [C8 sp]
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' P [C4 (wz 0); C4 mc]
    /\ rw_cells bsegs m' (TH + 3168) [C1 (b8 0)]
    /\ DEPOT bsegs d m'.

